import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cached component that fetches product data with cache tag
async function ProductList() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();
  const timestamp = new Date().toISOString();

  return (
    <div style={{ border: '1px solid #ddd', padding: '20px', marginBottom: '20px', borderRadius: '8px' }}>
      <h2>Product List</h2>
      <p style={{ color: '#666', fontSize: '14px' }}>
        Cached at: {timestamp}
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: '10px',
              margin: '5px 0',
              backgroundColor: '#f5f5f5',
              borderRadius: '4px',
              display: 'flex',
              justifyContent: 'space-between'
            }}
          >
            <span>{product.name}</span>
            <span style={{ fontWeight: 'bold' }}>${product.price}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  // Server action that invalidates the "products" cache
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Product Listing with Cache Invalidation</h1>

      <div style={{ marginBottom: '20px', padding: '15px', backgroundColor: '#e3f2fd', borderRadius: '8px' }}>
        <p style={{ margin: 0, fontSize: '14px' }}>
          <strong>Cache Strategy:</strong> The product list below is cached using the 'use cache' directive
          with a "products" cache tag. Click the button to selectively invalidate only the products cache.
        </p>
      </div>

      {/* Cached product list component */}
      <ProductList />

      {/* Form with inline server action for cache invalidation */}
      <form action={invalidateProducts}>
        <button
          type="submit"
          style={{
            padding: '12px 24px',
            backgroundColor: '#1976d2',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '16px',
            fontWeight: 'bold'
          }}
        >
          Invalidate Products Cache
        </button>
      </form>

      <div style={{ marginTop: '20px', padding: '15px', backgroundColor: '#fff3e0', borderRadius: '8px' }}>
        <h3 style={{ marginTop: 0 }}>How it works:</h3>
        <ol style={{ fontSize: '14px', lineHeight: '1.6' }}>
          <li><strong>Cache Directive:</strong> ProductList uses 'use cache' to enable caching</li>
          <li><strong>Cache Tag:</strong> Tagged with "products" for selective invalidation</li>
          <li><strong>Server Action:</strong> The form button triggers invalidateProducts()</li>
          <li><strong>Selective Invalidation:</strong> Only the "products" cache is cleared, not all caches</li>
          <li><strong>Timestamp:</strong> Shows when data was cached - watch it update after invalidation</li>
        </ol>
      </div>
    </div>
  );
}

